// Checks for the store (src/store.js): the crew screen opens it for one person and gets only that person's
// events plus the ship's, from our own server or, on a static copy, from the browser's storage, where the other
// people's events must stay untouched. The technical view still opens it for everyone.
// Run: npm test (Node 18+). Pretends to be a browser page with a stand-in location and storage.
// Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { openStore } from '../src/store.js';

const APP = fileURLToPath(new URL('..', import.meta.url));
const KEY = 'jff-health-events-v1';
const SWITCHES = { aiWorks: true, doctorOnBoard: false, linkToEarth: true };
const at = (m) => new Date(Date.now() - m * 60 * 1000).toISOString();
const reading = (person, value, m = 5, indicator = 'pulse', source = 'pulse-meter') => ({ v: 1, kind: 'reading', time: at(m), person, state: SWITCHES, reading: { source, indicator, value } });

// A stand-in for the browser: where the page was opened from, and its storage.
function pretendPage(href, storage) {
  const url = new URL(href);
  Object.defineProperty(globalThis, 'location', { value: { href: url.href, protocol: url.protocol, hostname: url.hostname }, configurable: true });
  Object.defineProperty(globalThis, 'localStorage', { value: storage, configurable: true });
}
function leavePage() {
  delete globalThis.location;
  delete globalThis.localStorage;
}
function memoryStorage(initial = {}) {
  const map = new Map(Object.entries(initial));
  return { map, getItem: (k) => (map.has(k) ? map.get(k) : null), setItem: (k, v) => map.set(k, String(v)), removeItem: (k) => map.delete(k) };
}

test('a static copy: one person reads only their own and the ship\'s events, and saving keeps everyone else\'s', async () => {
  const before = [reading('crew-1', 70, 30), reading('crew-2', 80, 29), reading('ship', 2.1, 28, 'co2', 'co2-sensor')];
  const storage = memoryStorage({ [KEY]: JSON.stringify(before) });
  pretendPage('https://team.github.io/crew-health/index.html', storage);
  try {
    const mine = await openStore({ person: 'crew-1' });
    assert.equal(mine.kind, 'browser');
    assert.equal(mine.scope, 'person');
    assert.equal(mine.person, 'crew-1');
    assert.deepEqual(mine.events.map((e) => e.person), ['crew-1', 'ship']);
    assert.equal(await mine.append(reading('crew-1', 72, 1)), null);
    await mine.append(reading('crew-2', 81, 1)); // restored from a file, say: kept, but not shown to crew-1
    assert.deepEqual(mine.events.map((e) => e.person), ['crew-1', 'ship', 'crew-1']);
    const saved = JSON.parse(storage.map.get(KEY));
    assert.deepEqual(saved.map((e) => e.person), ['crew-1', 'crew-2', 'ship', 'crew-1', 'crew-2'], 'nobody else\'s events are lost');
    assert.deepEqual(await mine.outbox(), [], 'a static copy has no outbox');
    const everyone = await openStore();
    assert.equal(everyone.scope, 'all');
    assert.equal(everyone.events.length, 5);
    assert.equal((await openStore({ all: true })).events.length, 5);
  } finally {
    leavePage();
  }
});

test('with storage blocked the store keeps things in memory and says so', async () => {
  pretendPage('https://team.github.io/crew-health/', { getItem() { throw new Error('blocked'); }, setItem() { throw new Error('blocked'); } });
  try {
    const s = await openStore({ person: 'crew-2' });
    assert.equal(s.kind, 'memory');
    await s.append(reading('crew-2', 60, 1));
    await s.append(reading('crew-1', 60, 1));
    assert.deepEqual(s.events.map((e) => e.person), ['crew-2']);
  } finally {
    leavePage();
  }
});

test('a person id that is not an id is refused before anything is read', async () => {
  await assert.rejects(openStore({ person: '../crew-1' }), TypeError);
  await assert.rejects(openStore({ person: 'Crew 1' }), TypeError);
});

test('our own server: the store asks for one person, saves through the checks and lists the outbox', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jff-store-'));
  const port = 20000 + Math.floor(Math.random() * 20000);
  const child = spawn(process.execPath, ['serve.mjs'], { cwd: APP, env: { ...process.env, HOSTS: '', OUTBOX_KEY_FILE: '', PORT: String(port), DATA_DIR: dir }, stdio: ['ignore', 'pipe', 'pipe'] });
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('server did not start')), 5000);
    child.stdout.on('data', (d) => { if (String(d).includes('running')) { clearTimeout(timer); resolve(); } });
    child.on('exit', (code) => { clearTimeout(timer); reject(new Error(`server exited ${code}`)); });
  });
  pretendPage(`http://127.0.0.1:${port}/index.html`, memoryStorage());
  try {
    const tech = await openStore();
    assert.equal(tech.kind, 'server');
    for (const e of [reading('crew-1', 70, 9), reading('crew-2', 75, 8), reading('ship', 2.1, 7, 'co2', 'co2-sensor')]) assert.equal(await tech.append(e), null);
    await assert.rejects(tech.append(reading('crew-1', 'abc', 6)), /not saved: 400 \(not a valid event: reading\.value/);
    const mine = await openStore({ person: 'crew-1' });
    assert.equal(mine.kind, 'server');
    assert.deepEqual(mine.events.map((e) => e.person), ['crew-1', 'ship']);
    const answer = await mine.append({ v: 1, kind: 'report', time: at(1), person: 'crew-1', state: SWITCHES, report: { to: 'doctor-earth', text: 'Please call me.' } });
    assert.equal(answer.outbox.status, 'queued');
    assert.equal(answer.outbox.encrypted, true);
    const waiting = await mine.outbox();
    assert.deepEqual(waiting.map((m) => [m.person, m.status]), [['crew-1', 'queued']]);
    assert.equal(waiting[0].body, undefined, 'the sealed text stays in the file');
    assert.deepEqual(await (await openStore({ person: 'crew-2' })).outbox(), []);
    assert.equal((await openStore()).events.length, 4);
  } finally {
    leavePage();
    child.kill();
    await rm(dir, { recursive: true, force: true });
  }
});
